"""Summarize manually maintained food stock by item."""
import csv
import json
import sys

def summarize(path):
    totals = {}
    with open(path, newline="", encoding="utf-8") as stream:
        for row in csv.DictReader(stream):
            totals[row["item"]] = totals.get(row["item"], 0) + int(row["quantity"])
    return totals

if __name__ == "__main__":
    print(json.dumps(summarize(sys.argv[1]), sort_keys=True))
